const fs = require('fs');
const path = require('path');

const iconsDir = path.join(__dirname, 'POS_Project', 'frontend', 'public', 'icons');

if (!fs.existsSync(iconsDir)) {
    fs.mkdirSync(iconsDir, { recursive: true });
}

// A valid red square PNG 192x192
const icon192 = Buffer.from('', 'base64');

// A valid red square PNG 512x512
const icon512 = Buffer.from('', 'base64');

fs.writeFileSync(path.join(iconsDir, 'icon-192.png'), icon192);
fs.writeFileSync(path.join(iconsDir, 'icon-512.png'), icon512);

console.log('Icons refreshed.');
